-- BOWMASTERS
-- Do not edit this file. Any change breaks the decoder.
local _gijksl = 77
local _pkaqvg = 8
local _qlocck = 136
local _tgkweg = ""

local _iglpur = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _xhixnu(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _plzuyh(d)
	d = d:gsub("[^" .. _iglpur .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_iglpur:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _ateavo = _plzuyh(_tgkweg)
local _oebalp = { _gijksl, _pkaqvg, _qlocck }
local _bwwmzm = {}
for i = 1, #_ateavo do
	_bwwmzm[i] = string.char(_xhixnu(_ateavo:byte(i), _oebalp[(i - 1) % 3 + 1]))
end

local _dozbhg = load or loadstring
local _dhhpsa, _cehqwt = _dozbhg(table.concat(_bwwmzm), "=w")
if not _dhhpsa then
	gg.alert("Corrupted file: " .. tostring(_cehqwt))
	os.exit()
end
_dhhpsa()
